// The Floors: requirements that the Prescription writes whatever the design is (SPEC.md section 2.18; decisions D13 and D70).
//
// Each record is data: an id, its Floor, its text for the AI coding tool, what a person must still check, its source (an address
// on one of five approved hosts and a short quotation), its grade, and its review date. The records come from the research records
// `docs/research/12a` to `12d`, whose quotations an independent helper compared with the pages on 2026-11-16 (decision D68). The
// records omit some rows of those research records on purpose; decision D70 lists each omission and its reason.
//
// What this file does not say. No program checks a Floor yet; the Fit check measures none of them. A requirement states what to
// build and what to check, never that a page meets a standard (hard rule 8). The Catalog grades are "measured", "convention", and
// "expert-opinion"; a requirement that a published standard states is graded "convention" and carries `standard: true`, because the
// three grades do not name a standard and a new grade would change a defined idea without the owner's word.

import type { Evidence } from './types.js';

export type FloorId = 'people' | 'page' | 'host' | 'search' | 'speed';

export interface FloorRule {
  /** A short id that the Prescription and the receipts use: A1 for people with disabilities, S for the page, H for the host, Q for search, P for speed. */
  id: string;
  floor: FloorId;
  /** What the AI coding tool must build, in exact terms. */
  text: string;
  /** What a person must still check; a program cannot. */
  person: string;
  source: { text: string; url: string };
  evidence: Evidence;
  /** True only when a published standard states the requirement in words close to the text; a recommendation of a guide is not a standard. */
  standard: boolean;
  /** Where the standard states it (for the people Floor: the success criterion), when the source names a place. */
  where?: string;
  reviewed: string;
  /** How a program could check the requirement, from the research record. The Prescription does not print it and no program runs it yet. */
  program: string;
}

export interface FloorInfo {
  id: FloorId;
  name: string;
  /** What the Floor is, in plain words. */
  what: string;
}

export const FLOORS: readonly FloorInfo[] = [
  { id: 'people', name: 'Use by people with disabilities', what: 'Requirements that let a person who cannot see, hear, hold a mouse, or read small text use the page. Written only when Contrast checks is “Fix for me” (decision D13).' },
  { id: 'page', name: 'Security of the page', what: 'What the page itself must and must not contain, so that nothing on it can be used against the people who visit it.' },
  { id: 'host', name: 'Security settings of the host', what: 'Settings that the place that serves the page must make. A page of one file cannot send them; a person must set them at the host.' },
  { id: 'search', name: 'Being found by search', what: 'What a search engine needs on the page in order to find it, read it, and describe it. Some of these requirements (language, title, text for images, link text, zooming) also serve people with disabilities; they stand here for search whatever the contrast setting is.' },
  { id: 'speed', name: 'Speed', what: 'Limits on how fast the page appears and how steady it stays while it loads.' },
];

